                                                             'competition. Classical '
                                                             'Hansch equations '
                                                             'correlate potency with '
                                                             'hydrophobic, electronic '
                                                             '(Hammett σ), and steric '
                                                             'parameters as a '
                                                             'foundation for modern '
                                                             'QSAR thinking.',
